    def runs(coords):
        result = []
        i = 0
        while i < len(coords):
            r, c = coords[i]
            color = grid[r][c]
            if color == bg:
                i += 1
                continue
            j = i + 1
            while j < len(coords) and grid[coords[j][0]][coords[j][1]] == color:
                j += 1
            if j - i >= 2:
                result.append((color, i, j))
            i = j
        return result

    top = runs([(0, c) for c in range(w)])
    bottom = runs([(h - 1, c) for c in range(w)])
    left = runs([(r, 0) for r in range(h)])
    right = runs([(r, w - 1) for r in range(h)])
    pairs = []
    for side_a, side_b, ra, rb in (("top", "bottom", top, bottom), ("left", "right", left, right)):
