                continue
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if j - i >= 2:
                runs.append((values[i], i, j))
            i = j
        return runs

    # Pair equal-color, equal-length edge bars on opposite sides.
    pairs = []
    for first, second, a_runs, b_runs in (
        ('top', 'bottom', edge_runs(grid[0]), edge_runs(grid[-1])),
        ('left', 'right', edge_runs([grid[r][0] for r in range(h)]),
         edge_runs([grid[r][-1] for r in range(h)])),
    ):
        for color, a, b in a_runs:
            for other_color, x, y in b_runs:
                if color == other_color and b - a == y - x:
                    pairs.append((first, second, color, a, b, x))
                    break

    bar_cells = set()
    for side, runs in (
        ('top', edge_runs(grid[0])), ('bottom', edge_runs(grid[-1])),
        ('left', edge_runs([grid[r][0] for r in range(h)])),
        ('right', edge_runs([grid[r][-1] for r in range(h)])),
    ):
        for _, start, end in runs:
            for pos in range(start, end):
                if side == 'top': bar_cells.add((0, pos))
                elif side == 'bottom': bar_cells.add((h-1, pos))
                elif side == 'left': bar_cells.add((pos, 0))
                else: bar_cells.add((pos, w-1))

    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != background and (r, c) not in bar_cells]

