    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    freq = {}
    for row in grid:
        for value in row:
            freq[value] = freq.get(value, 0) + 1
    background = max(freq, key=freq.get)

    def runs(values):
        result = []
        i = 0
        while i < len(values):
            if values[i] == background:
                i += 1
                continue
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if j - i >= 2:
                result.append((values[i], i, j))
            i = j
        return result

    top = runs(grid[0])
    bottom = runs(grid[-1])
    left = runs([grid[r][0] for r in range(h)])
    right = runs([grid[r][-1] for r in range(h)])

    pairs = []
    for side_a, side_b, bars_a, bars_b in (
        ('top', 'bottom', top, bottom),
        ('left', 'right', left, right),
    ):
        used = set()
        for color, start, end in bars_a:
            length = end - start
            for index, (other_color, other_start, other_end) in enumerate(bars_b):
                if index not in used and other_color == color and other_end-other_start == length:
                    pairs.append((side_a, side_b, start, other_start, length))
                    used.add(index)
                    break

    def point(side, pos, inward):
        if side == 'top':
            return (inward, pos)
        if side == 'bottom':
            return (h - 1 - inward, pos)
        if side == 'left':
            return (pos, inward)
        return (pos, w - 1 - inward)

    def max_depth(side):
        return h - 2 if side in ('top', 'bottom') else w - 2

    for side_a, side_b, start_a, start_b, length in pairs:
        for slot in range(length):
            pos_a, pos_b = start_a + slot, start_b + slot
            # Markers on either corresponding ray activate both projections.
            markers = []
            for side, pos in ((side_a, pos_a), (side_b, pos_b)):
                for depth in range(1, max_depth(side) + 1):
                    r, c = point(side, pos, depth)
                    if grid[r][c] != background:
                        markers.append((side, pos, depth, grid[r][c]))
                        break
            for marker_side, marker_pos, marker_depth, marker_color in markers:
                # From the marker's own edge, fill only up to its marker.
                for depth in range(1, marker_depth):
                    r, c = point(marker_side, marker_pos, depth)
                    if grid[r][c] == background:
                        out[r][c] = marker_color
                mr, mc = point(marker_side, marker_pos, marker_depth)
                out[mr][mc] = 4
                # Matching slot on the opposite edge projects fully inward,
                # stopping at any existing non-background object.
                opposite_side = side_b if marker_side == side_a else side_a
                opposite_pos = pos_b if marker_side == side_a else pos_a
                for depth in range(1, max_depth(opposite_side) + 1):
                    r, c = point(opposite_side, opposite_pos, depth)
                    if grid[r][c] != background:
                        break
                    out[r][c] = marker_color
    return out

