        i = 0
        while i < len(values):
            if values[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if j - i >= 2:
                ans.append((values[i], i, j))
            i = j
        return ans

    sides = {
        'top': runs(grid[0]),
        'bottom': runs(grid[-1]),
        'left': runs([grid[r][0] for r in range(h)]),
        'right': runs([grid[r][-1] for r in range(h)]),
    }
    pairs = []
    for a, b in (('top', 'bottom'), ('left', 'right')):
        for color, start, end in sides[a]:
            mate = next(((s, e) for c, s, e in sides[b]
                         if c == color and e - s == end - start), None)
            if mate:
                pairs.append((a, b, start, mate[0], end - start))

    def coordinate(side, position, depth):
        if side == 'top': return depth, position
        if side == 'bottom': return h - 1 - depth, position
        if side == 'left': return position, depth
        return position, w - 1 - depth

    for side_a, side_b, start_a, start_b, length in pairs:
        for offset in range(length):
            pos_a, pos_b = start_a + offset, start_b + offset
            maxdepth = h - 1 if side_a in ('top', 'bottom') else w - 1
