    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    freq = {}
    for row in grid:
        for value in row:
            freq[value] = freq.get(value, 0) + 1
    bg = max(freq, key=freq.get)

    def runs(values):
        result = []
        i = 0
        while i < len(values):
            if values[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if j - i >= 2:
                result.append((values[i], i, j))
            i = j
        return result

    def cast_line(coords, marker_color):
        # Stop at the first non-background cell. A marker is changed to 4;
        # all empty cells before it are filled with its original color.
        for r, c in coords:
            if grid[r][c] != bg:
                if out[r][c] != 4:
                    out[r][c] = 4
                break
            out[r][c] = marker_color

    edges = {
        'top': runs(grid[0]),
        'bottom': runs(grid[-1]),
        'left': runs([grid[r][0] for r in range(h)]),
        'right': runs([grid[r][-1] for r in range(h)]),
    }
    for side_a, side_b in (('top', 'bottom'), ('left', 'right')):
        used = set()
        for color, a, b in edges[side_a]:
            mate_index = None
            for j, (other, x, y) in enumerate(edges[side_b]):
                if j not in used and other == color and y - x == b - a:
                    mate_index = j
                    break
            if mate_index is None:
                continue
            used.add(mate_index)
            _, x, y = edges[side_b][mate_index]
            for offset in range(b - a):
                pa, pb = a + offset, x + offset
                # A marker on either corresponding ray projects its own color
                # from its edge toward itself and from the opposite edge up to
                # the first obstruction.
                for side, pos, other_side, other_pos in (
                    (side_a, pa, side_b, pb), (side_b, pb, side_a, pa)
                ):
                    if side == 'top':
                        first = [(r, pos) for r in range(1, h - 1)]
                        second = [(r, other_pos) for r in range(1, h - 1)]
                    elif side == 'bottom':
                        first = [(r, pos) for r in range(h - 2, 0, -1)]
                        second = [(r, other_pos) for r in range(h - 2, 0, -1)]
                    elif side == 'left':
                        first = [(pos, c) for c in range(1, w - 1)]
                        second = [(other_pos, c) for c in range(1, w - 1)]
                    else:
