        for color, start, end in runs(va):
            for ix, (other, start_b, end_b) in enumerate(runs(vb)):
                if ix not in used and color == other and end-start == end_b-start_b:
                    pairs.append((side_a, side_b, start, start_b, end-start))
                    used.add(ix)
                    break

    def ray_cell(side, pos, depth):
        if side == 'top': return depth, pos
        if side == 'bottom': return h - 1 - depth, pos
        if side == 'left': return pos, depth
        return pos, w - 1 - depth

    def ray_size(side):
        return h if side in ('top', 'bottom') else w

