    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Detect paired bars along every opposite edge pair.
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    def runs(vals):
        found, i = [], 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < len(vals) and vals[j] == vals[i]:
                j += 1
            if j-i >= 2:
                found.append((vals[i], i, j))
            i = j
        return found

    pairs = []
    for a, b, va, vb in (
        ('top', 'bottom', grid[0], grid[-1]),
        ('left', 'right', [grid[r][0] for r in range(h)], [grid[r][-1] for r in range(h)]),
    ):
        used = set()
        rb = runs(vb)
        for color, s, e in runs(va):
            for i, (c2, s2, e2) in enumerate(rb):
                if i not in used and color == c2 and e-s == e2-s2:
                    pairs.append((a, b, s, s2, e-s))
                    used.add(i)
                    break

    def cell(side, pos, depth):
        if side == 'top': return depth, pos
        if side == 'bottom': return h-1-depth, pos
        if side == 'left': return pos, depth
        return pos, w-1-depth

    def ndepth(side):
        return h-1 if side in ('top','bottom') else w-1

    for a, b, sa, sb, length in pairs:
        for k in range(length):
            pa, pb = sa+k, sb+k
            for side, pos, other, opos in ((a,pa,b,pb),(b,pb,a,pa)):
                # The first encountered non-background cell on this ray is a
                # marker. Fill its ray from the edge to the marker; 4 marks it.
                marker = None
                for d in range(1, ndepth(side)+1):
                    r,c = cell(side,pos,d)
                    if grid[r][c] != bg:
                        marker = (d,r,c,grid[r][c])
                        break
                if marker is None:
                    continue
                d,mr,mc,color = marker
                for x in range(1,d):
                    r,c = cell(side,pos,x)
                    if grid[r][c] == bg:
                        out[r][c] = color
                out[mr][mc] = 4
