 "content": "def transform(grid):
    """Project a marker's color through aligned rays between equal edge bars."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    freq = {}
    for row in grid:
        for value in row:
            freq[value] = freq.get(value, 0) + 1
    bg = max(freq, key=freq.get)

    def runs(values):
        result = []
        i = 0
        while i < len(values):
            if values[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if j - i >= 2:
                result.append((values[i], i, j))
            i = j
        return result

    top, bottom = runs(grid[0]), runs(grid[-1])
    for bar_color, start, end in top:
        mate = next(((s, e) for c, s, e in bottom
                     if c == bar_color and e - s == end - start), None)
        if mate is None:
            continue
        bottom_start, _ = mate
        for offset in range(end - start):
            col_top = start + offset
            col_bottom = bottom_start + offset
            for col, opp_col, side in ((col_top, col_bottom, 'top'),
                                       (col_bottom, col_top, 'bottom')):
                # Read markers from the original grid, nearest first.
                markers = [(r, grid[r][col]) for r in range(1, h - 1)
                           if grid[r][col] != bg]
                if not markers:
                    continue
                if side == 'top':
                    r, marker_color = markers[0]
                    for rr in range(1, r):
                        if grid[rr][col] == bg:
                            out[rr][col] = marker_color
                    out[r][col] = 4
                    for rr in range(1, h - 1):
                        if grid[rr][opp_col] != bg:
                            break
                        out[rr][opp_col] = marker_color
                else:
                    r, marker_color = markers[-1]
                    for rr in range(r + 1, h - 1):
                        if grid[rr][col] == bg:
                            out[rr][col] = marker_color
                    out[r][col] = 4
                    for rr in range(h - 2, 0, -1):
                        if grid[rr][opp_col] != bg:
                            break
                        out[rr][opp_col] = marker_color
    return out

if __name__ == '__main__':
