 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def runs(values):
        found = []
        i = 0
        while i < len(values):
            if values[i] == background:
                i += 1
                continue
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if j - i >= 2:
                found.append((values[i], i, j))
            i = j
        return found

    # Matching bars on opposite horizontal edges pair their slots. A marker
    # on one bar's lane paints toward its own edge and projects a full ray on
    # the paired lane; markers are replaced with 4.
    top_bars, bottom_bars = runs(grid[0]), runs(grid[-1])
    for color, top_start, top_end in top_bars:
        match = next(((s, e) for c, s, e in bottom_bars
                      if c == color and e - s == top_end - top_start), None)
        if match is None:
            continue
        bottom_start, _ = match
        for offset in range(top_end - top_start):
            top_col = top_start + offset
            bottom_col = bottom_start + offset
            # Top-origin marker: fill from top to marker and project down
            # the matching bottom-bar lane.
            for r in range(1, h - 1):
                if grid[r][top_col] == background:
                    continue
                marker_color = grid[r][top_col]
                for rr in range(1, r):
                    if grid[rr][top_col] == background:
                        out[rr][top_col] = marker_color
                for rr in range(1, h - 1):
                    if grid[rr][bottom_col] == background:
                        out[rr][bottom_col] = marker_color
                out[r][top_col] = 4
            # Bottom-origin marker: fill from marker to bottom and project up
            # the matching top-bar lane.
            for r in range(h - 2, 0, -1):
                if grid[r][bottom_col] == background:
                    continue
                marker_color = grid[r][bottom_col]
                for rr in range(r + 1, h - 1):
                    if grid[rr][bottom_col] == background:
                        out[rr][bottom_col] = marker_color
                for rr in range(1, h - 1):
                    if grid[rr][top_col] == background:
                        out[rr][top_col] = marker_color
                out[r][bottom_col] = 4
    return out

