 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def runs(values):
        result = []
        i = 0
        while i < len(values):
            if values[i] == background:
                i += 1
                continue
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if j - i >= 2:
                result.append((values[i], i, j))
            i = j
        return result

    edges = {
        "top": runs(grid[0]),
        "bottom": runs(grid[-1]),
        "left": runs([grid[r][0] for r in range(h)]),
        "right": runs([grid[r][-1] for r in range(h)]),
    }
    pairs = []
    for a, b in (("top", "bottom"), ("left", "right")):
        for color, start, end in edges[a]:
            for other_color, other_start, other_end in edges[b]:
                if color == other_color and end - start == other_end - other_start:
                    pairs.append((a, b, start, other_start, end - start))
                    break

    bar_cells = set()
    for side, edge_runs in edges.items():
        for _, start, end in edge_runs:
            for p in range(start, end):
                if side == "top": bar_cells.add((0, p))
                elif side == "bottom": bar_cells.add((h - 1, p))
                elif side == "left": bar_cells.add((p, 0))
                else: bar_cells.add((p, w - 1))

    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != background and (r, c) not in bar_cells]

    for r, c, color in markers:
        for side_a, side_b, start_a, start_b, length in pairs:
            axis = c if side_a == "top" else r
            for side, start, other_side, other_start in (
                (side_a, start_a, side_b, start_b),
                (side_b, start_b, side_a, start_a),
            ):
                if not (start <= axis < start + length):
                    continue
                slot = axis - start
                marker_is_interior = 0 < r < h - 1 and 0 < c < w - 1
                if not marker_is_interior:
                    continue
                if side in ("top", "bottom"):
                    edge_r = 0 if side == "top" else h - 1
                    dr = 1 if side == "top" else -1
                    rr = edge_r + dr
                    while 0 < rr < h - 1:
                        if (rr, axis) == (r, c):
                            out[rr][axis] = 4
                            break
                        if grid[rr][axis] != background:
                            break
                        out[rr][axis] = color
                        rr += dr
                else:
                    edge_c = 0 if side == "left" else w - 1
                    dc = 1 if side == "left" else -1
                    cc = edge_c + dc
                    while 0 < cc < w - 1:
                        if (axis, cc) == (r, c):
                            out[axis][cc] = 4
                            break
                        if grid[axis][cc] != background:
                            break
                        out[axis][cc] = color
                        cc += dc

                paired_pos = other_start + slot
                if other_side in ("top", "bottom"):
                    edge_r = 0 if other_side == "top" else h - 1
                    dr = 1 if other_side == "top" else -1
                    rr = edge_r + dr
                    while 0 < rr < h - 1:
                        if grid[rr][paired_pos] != background:
                            break
                        out[rr][paired_pos] = color
                        rr += dr
                else:
                    edge_c = 0 if other_side == "left" else w - 1
                    dc = 1 if other_side == "left" else -1
                    cc = edge_c + dc
                    while 0 < cc < w - 1:
                        if grid[paired_pos][cc] != background:
                            break
                        out[paired_pos][cc] = color
                        cc += dc
    return out

